	let ytpre="https://www.youtube.com/watch?v="
	if( href.toLowerCase().substr(0,ytpre.length) == ytpre )
	{
		let VIDEO_ID=href.substr(ytpre.length,11)
		let div=document.createElement("div")
		div.innerHTML=`
<iframe width="820" height="600" src="https://www.youtube.com/embed/${VIDEO_ID}" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
		`

		link.after(div)
	}
	else
	{
		switch(ext.toLowerCase())
		{
			case "png":
				link.innerHTML=`<image src="${href}"></image>`
			break;
		}
	}

}

